  const cnt = new Array(26).fill(0);
  for (const ch of s) cnt[ch.charCodeAt(0) - 97] += 1;
  const n = s.length;
  let peak0 = 0;
  for (const c of cnt) if (c > peak0) peak0 = c;
  if (peak0 > Math.ceil(n / 2)) return "";
  const memo = new Map();
  function go(counts, prev) {
    let total = 0;
    for (const c of counts) total += c;
    if (total === 0) return "";
    const key = counts.join(",") + "|" + prev;
    if (memo.has(key)) return memo.get(key);
    let best = null;
    for (let c = 0; c < 26; c++) {
      if (counts[c] === 0 || c === prev) continue;
      counts[c] -= 1;
      const rest = go(counts, c);
      counts[c] += 1;
      if (rest !== null) {
        const cand = String.fromCharCode(97 + c) + rest;
        if (best === null || cand < best) best = cand;
      }
    }
    memo.set(key, best);
    return best;
  }
  const res = go(cnt, -1);
  return res === null ? "" : res;
}

function solve(s) {
  const cnt = new Array(26).fill(0);
  for (const ch of s) cnt[ch.charCodeAt(0) - 97] += 1;
  const n = s.length;
  let peak0 = 0;
  for (const c of cnt) if (c > peak0) peak0 = c;
  if (peak0 > Math.ceil(n / 2)) return "";
  function feasible(counts, prev) {
    let m = 0;
    let peak = 0;
    let arg = -1;
    for (let c = 0; c < 26; c++) {
      m += counts[c];
      if (counts[c] > peak) {
        peak = counts[c];
        arg = c;
      }
    }
    if (m === 0) return true;
    if (peak <= Math.floor(m / 2)) return true;
    if (m % 2 === 1 && peak === (m + 1) / 2) return prev !== arg;
    return false;
  }
  const out = [];
  let prev = -1;
  for (let pos = 0; pos < n; pos++) {
    for (let c = 0; c < 26; c++) {
      if (cnt[c] === 0 || c === prev) continue;
      cnt[c] -= 1;
      if (feasible(cnt, c)) {
        out.push(String.fromCharCode(97 + c));
        prev = c;
        break;
      }
      cnt[c] += 1;
    }
  }
  return out.join("");
}
